import { useEffect, useReducer } from "react";
import { fetchTags } from "../services/tagsApi";

const INITIAL_STATE = {
  tags: [],
  loading: true,
  error: "",
};

function isCanceledError(requestError) {
  return (
    requestError?.name === "CanceledError" ||
    requestError?.code === "ERR_CANCELED"
  );
}

function popularTagsReducer(state, action) {
  switch (action.type) {
    case "load-start":
      return {
        ...state,
        loading: true,
        error: "",
      };
    case "load-success":
      return {
        tags: action.tags,
        loading: false,
        error: "",
      };
    case "load-error":
      return {
        tags: [],
        loading: false,
        error: "Tags list not available",
      };
    default:
      return state;
  }
}

function usePopularTags() {
  const [state, dispatch] = useReducer(popularTagsReducer, INITIAL_STATE);

  useEffect(() => {
    const controller = new AbortController();

    async function loadTags() {
      dispatch({ type: "load-start" });

      try {
        const nextTags = await fetchTags(controller.signal);
        dispatch({ type: "load-success", tags: nextTags });
      } catch (requestError) {
        if (!isCanceledError(requestError)) {
          dispatch({ type: "load-error" });
          console.error(requestError);
        }
      }
    }

    loadTags();

    return () => {
      controller.abort();
    };
  }, []);

  return state;
}

export default usePopularTags;

import usePopularTags from "../../hooks/usePopularTags";

const MAX_TAGS = 50;

function PopularTags() {
  const { tags, loading, error } = usePopularTags();

  let content = <p>Tags list not available</p>;

  if (loading) {
    content = <p>Loading tags...</p>;
  } else if (error) {
    content = <p>{error}</p>;
  } else if (tags.length > 0) {
    content = (
      <ul className="tag-list-items">
        {tags.slice(0, MAX_TAGS).map((name) => (
          <li key={name}>
            <button className="tag-pill tag-default" type="button">
              {name}
            </button>
          </li>
        ))}
      </ul>
    );
  }

  return (
    <aside className="col-md-3">
      <div className="sidebar">
        <h6>Popular Tags</h6>
        <div className="tag-list">{content}</div>
      </div>
    </aside>
  );
}

export default PopularTags;

import usePopularTags from "../../hooks/usePopularTags";

const MAX_TAGS = 50;

function renderTags(tags) {
  return (
    <ul className="tag-list-items">
      {tags.slice(0, MAX_TAGS).map((name) => (
        <li key={name}>
          <button className="tag-pill tag-default" type="button">
            {name}
          </button>
        </li>
      ))}
    </ul>
  );
}

function getContent({ tags, loading, error }) {
  if (loading) {
    return <p>Loading tags...</p>;
  }

  if (error) {
    return <p>{error}</p>;
  }

  if (tags.length > 0) {
    return renderTags(tags);
  }

  return <p>Tags list not available</p>;
}

function PopularTags() {
  const { tags, loading, error } = usePopularTags();

  return (
    <aside className="col-md-3">
      <div className="sidebar">
        <h6>Popular Tags</h6>
        <div className="tag-list">{getContent({ tags, loading, error })}</div>
      </div>
    </aside>
  );
}

export default PopularTags;
